import React, { useState } from 'react';
import Navbar from './components/Navbar';
import Home from './components/Home';
import Timetable from './components/Timetable';
import Teachers from './components/Teachers';
import About from './components/About';
import LmsDashboard from './components/LmsDashboard';
import Footer from './components/Footer';

export default function App() {
  const [currentPage, setCurrentPage] = useState('Home');
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [studentName, setStudentName] = useState('');
  const [inputName, setInputName] = useState('');
  const [inputPassword, setInputPassword] = useState('');

  const handleLoginSubmit = async (e) => {
    e.preventDefault();
    try {
      const response = await fetch('http://localhost:5000/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username: inputName, password: inputPassword })
      });
      const data = await response.json();
      if (data.status === 'Success') {
        setStudentName(inputName);
        setIsLoggedIn(true);
        setShowLoginModal(false);
        setCurrentPage('Dashboard');
      } else {
        alert('Invalid Username or Password!');
      }
    } catch (error) {
      alert('Error: Server connection failed!');
    }
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setStudentName('');
    setInputName('');
    setInputPassword('');
    setCurrentPage('Home');
  };

  return (
    <div style={{ margin: 0, padding: 0, fontFamily: 'Arial, sans-serif', backgroundColor: '#f4f6f9', minHeight: '100vh' }}>
      <Navbar 
        onLoginClick={() => setShowLoginModal(true)} 
        isLoggedIn={isLoggedIn} 
        studentName={studentName} 
      />

      {currentPage === 'Home' && <Home />}
      {currentPage === 'Classes' && <Timetable />}
      {currentPage === 'Teachers' && <Teachers />}
      {currentPage === 'About' && <About />}
      {currentPage === 'Dashboard' && <LmsDashboard username={studentName} onLogout={handleLogout} />}

      <Footer />

  {showLoginModal && (
  <div
    style={{
      position: 'fixed',
      top: 0,
      left: 0,
      width: '100%',
      height: '100%',
      background: 'rgba(0,0,0,0.45)',
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      zIndex: 2000,
      backdropFilter: 'blur(4px)',
    }}
  >
    <div
      style={{
        width: '900px',
        height: '500px',
        background: '#fff',
        borderRadius: '25px',
        overflow: 'hidden',
        display: 'flex',
        boxShadow: '0 20px 50px rgba(0,0,0,0.25)',
        fontFamily: 'Poppins, sans-serif',
      }}
    >
      <div
        style={{
          flex: 1,
          background: 'linear-gradient(135deg, #386641, #6a994e, #a7c957)',
          position: 'relative',
          color: '#fff',
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'center',
          padding: '60px',
          overflow: 'hidden',
        }}
      >
        <div
          style={{
            position: 'absolute',
            width: '280px',
            height: '280px',
            borderRadius: '50%',
            background: 'rgba(255,255,255,0.12)',
            top: '40px',
            left: '-70px',
          }}
        />
        <div
          style={{
            position: 'absolute',
            width: '140px',
            height: '140px',
            borderRadius: '50%',
            background: 'rgba(255,255,255,0.15)',
            bottom: '-30px',
            right: '-20px',
          }}
        />
        <div
          style={{
            position: 'absolute',
            top: '60px',
            right: '70px',
            width: '15px',
            height: '15px',
            borderRadius: '50%',
            border: '2px solid #fff',
          }}
        />
        <div
          style={{
            position: 'absolute',
            bottom: '90px',
            left: '70px',
            display: 'grid',
            gridTemplateColumns: 'repeat(4, 10px)',
            gap: '8px',
          }}
        >
          {[...Array(12)].map((_, i) => (
            <div
              key={i}
              style={{
                width: '5px',
                height: '5px',
                background: '#fff',
                borderRadius: '50%',
                opacity: 0.8,
              }}
            />
          ))}
        </div>
        <div style={{ zIndex: 2 }}>
          <h1 style={{ fontSize: '52px', fontWeight: '700', marginBottom: '10px', lineHeight: '1.1' }}>
            Aura Pen
          </h1>
          <p style={{ fontSize: '24px', opacity: 0.9, lineHeight: '1.5' }}>
            Educational Institute
          </p>
        </div>
      </div>
      <div
        style={{
          flex: 1,
          background: '#ffffff',
          padding: '60px',
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'center',
        }}
      >
        <h2 style={{ fontSize: '45px', color: '#386641', marginBottom: '35px', fontWeight: '700' }}>
          Welcome Back!
        </h2>
        <form onSubmit={handleLoginSubmit}>
          <div style={{ marginBottom: '20px' }}>
            <label style={{ display: 'block', marginBottom: '8px', fontWeight: '600', color: '#222' }}>
              User Name
            </label>
            <input
              type="text"
              placeholder="Enter your user name"
              required
              onChange={(e) => setInputName(e.target.value)}
              style={{ width: '100%', padding: '16px 20px', borderRadius: '40px', border: '1px solid #ccc', outline: 'none', fontSize: '15px', boxSizing: 'border-box' }}
            />
          </div>
          <div style={{ marginBottom: '15px' }}>
            <label style={{ display: 'block', marginBottom: '8px', fontWeight: '600', color: '#222' }}>
              Password
            </label>
            <input
              type="password"
              placeholder="Enter your password"
              required
              onChange={(e) => setInputPassword(e.target.value)}
              style={{ width: '100%', padding: '16px 20px', borderRadius: '40px', border: '1px solid #ccc', outline: 'none', fontSize: '15px', boxSizing: 'border-box' }}
            />
          </div>
          <p style={{ fontSize: '13px', color: '#777', marginBottom: '25px', lineHeight: '1.5' }}>
            If you forgot your username or password, please contact the institute.
          </p>
          <button
            type="submit"
            style={{
              width: '100%',
              padding: '16px',
              border: 'none',
              borderRadius: '40px',
              background: 'linear-gradient(90deg, #386641, #6a994e)',
              color: '#fff',
              fontSize: '18px',
              fontWeight: '600',
              cursor: 'pointer',
              transition: '0.3s',
              boxShadow: '0 10px 20px rgba(56,102,65,0.3)',
            }}
          >
            Login
          </button>
        </form>
      </div>
    </div>
  </div>
)}
</div>
  );}
